function exportExcel(fileName,sheetName,headers,rows){const row=cells=>`<Row>${cells.map(value=>`<Cell><Data ss:Type="String">${excelEsc(value)}</Data></Cell>`).join('')}</Row>`,xml=`<?xml version="1.0" encoding="UTF-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="${excelEsc(sheetName).slice(0,31)}"><Table>${row(headers)}${rows.map(row).join('')}</Table></Worksheet></Workbook>`,url=URL.createObjectURL(new Blob([xml],{type:'application/vnd.ms-excel;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=fileName.replace(/[^a-z0-9._-]+/gi,'-')+'.xls';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
