function setAppLoading(active,label='Loading...'){
 const overlay=document.getElementById('app-loading');
 loadingTasks=Math.max(0,loadingTasks+(active?1:-1));
 if(active)document.getElementById('app-loading-label').textContent=label;
 overlay.hidden=loadingTasks===0;
 document.body.classList.toggle('app-is-loading',loadingTasks>0);
}
async function api(path,method='GET',body){
 const foreground=method!=='GET';
 if(foreground)setAppLoading(true);
 try{return await request(path,method,body);}finally{if(foreground)setAppLoading(false);}
}
