function heading(title,description,actions=''){return `<div class="page-heading"><div><h1 class="page-title">${esc(title)}</h1><p class="page-subtitle">${esc(description)}</p></div><div class="heading-actions">${actions}</div></div>`;}
function empty(text){return `<div class="empty-state">${esc(text)}</div>`;}
function connectionAlerts(){
 const unavailable=workspace.numbers.filter(number=>number.status==='Session expired'||number.status==='Disconnected');
 if(!unavailable.length)return '';
 return `<section class="connection-alert" role="alert" aria-labelledby="connection-alert-title"><div class="connection-alert-icon" aria-hidden="true">!</div><div class="connection-alert-content"><b id="connection-alert-title">WhatsApp connection needs attention</b><p>${unavailable.some(number=>number.status==='Session expired')?'One or more WhatsApp sessions were logged out. Reconnect them by scanning a new QR code.':'A WhatsApp number is temporarily disconnected. Relay will keep retrying automatically.'}</p><div class="connection-alert-accounts">${unavailable.map(number=>`<div><span><strong>${esc(number.name)}</strong>${number.phone?` <small>${esc(number.phone)}</small>`:''} <em>${esc(number.status)}</em></span><button class="btn" data-action="reconnect" data-id="${esc(number.id)}">${number.status==='Session expired'?'Reconnect':'Retry now'}</button></div>`).join('')}</div></div></section>`;
}
function accountStatusClass(status){return status==='Connected'?'connected':status==='Connecting'||status==='Awaiting scan'?'pending':'disconnected';}
function renderNotificationCenter(){}
function browserConnectionNotification(number,connected){
 if(typeof Notification==='undefined'||Notification.permission!=='granted')return;
 const notice=new Notification(connected?'WhatsApp account connected':'WhatsApp account disconnected',{body:`${number.name}${number.phone?' ('+number.phone+')':''} ${connected?'is connected and ready.':'is '+number.status.toLowerCase()+'.'}`,tag:'relay-whatsapp-'+number.id,renotify:true});
 notice.onclick=()=>{window.focus();notice.close();};
}
function trackAccountStatuses(numbers){
 const next=new Map(numbers.map(number=>[number.id,number.status]));
 if(knownAccountStatuses)for(const number of numbers){const previous=knownAccountStatuses.get(number.id);if(previous==='Connected'&&accountStatusClass(number.status)==='disconnected')browserConnectionNotification(number,false);else if(previous&&previous!=='Connected'&&number.status==='Connected')browserConnectionNotification(number,true);}
 knownAccountStatuses=next;
}
function filterTrigger(){const count=Object.values(directoryFilters[filterKey()]).filter(value=>value&&value!=='all').length,available=['conversations','contacts','groups'].includes(state.page);return `<div class="header-filter-actions"><button id="directory-filter-trigger" class="filter-trigger" data-action="open-directory-filters" aria-haspopup="dialog">Filters${count?' ('+count+')':''}</button>${available?`<button class="smart-list-toggle ${state.smartListsOpen?'open':''}" data-action="toggle-smart-lists" aria-label="${state.smartListsOpen?'Hide smart lists':'Show smart lists'}" aria-expanded="${state.smartListsOpen}" title="${state.smartListsOpen?'Hide smart lists':'Show smart lists'}"><span aria-hidden="true"></span></button>`:''}</div>`;}
