function bulkContactToolbar(){return `<div class="bulk-contact-toolbar"><label><input type="checkbox" data-select-all-contacts aria-label="Select all visible contacts"> Select all</label><div class="contact-table-actions">${state.page==='contacts'?'<button class="btn" data-action="show-hidden-contacts">Hidden contacts</button><button class="btn" data-action="export-directory">Export</button><button class="btn btn-primary" data-action="new-crm-contact">New contact</button>':state.page==='groups'?'<button class="btn" data-action="show-hidden-groups">Hidden groups</button><button class="btn" data-action="export-directory">Export</button>':''}<button class="btn btn-danger" data-action="delete-selected-contacts" ${state.selectedContacts.size?'':'hidden'} ${state.bulkDeleting?'disabled':''}>Delete selected (${state.selectedContacts.size})</button></div></div>`;}
function contactTable(entities){return entities.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th aria-label="Select contacts"></th><th>CONTACT / GROUP</th><th>PHONE NUMBER</th><th>EMPLOYEE</th><th>BRANCHES / RESPONSIBLE</th><th>LAST MESSAGE</th></tr></thead><tbody>${entities.map(e=>`<tr class="clickable-row" data-open-contact="${esc(e.id)}"><td>${e.kind!=='group'?`<input type="checkbox" class="contact-checkbox" data-contact-check="${esc(contactSelectionId(e))}" aria-label="Select ${esc(e.name)}" ${state.selectedContacts.has(contactSelectionId(e))?'checked':''}>`:''}</td><td><b>${esc(e.name)}</b><small>${e.kind==='group'?'Group':'Contact'}</small></td><td>${esc(e.kind==='group'?'Group chat':e.phone||'Number not provided by WhatsApp')}</td><td>${employeeNames(e,workspace).map(name=>`<div>${esc(name)}</div>`).join('')||'Not assigned'}</td><td>${esc(branchLabels(e.branchIds))}<small>${esc(e.responsible)}</small></td><td>${esc(e.last?.body||'No messages received')}<small>${esc(date(e.last?.created_at))}</small></td></tr>`).join('')}</tbody></table></div>`:empty('No contacts or groups with captured messages match these filters.');}
function groupTable(groups){return groups.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th aria-label="Select groups"></th><th>GROUP</th><th>MEMBERS</th><th>EMPLOYEE</th><th>BRANCHES</th><th>LAST MESSAGE</th></tr></thead><tbody>${groups.map(group=>`<tr class="clickable-row" data-open-group="${esc(group.id)}" tabindex="0"><td><input type="checkbox" class="contact-checkbox" data-contact-check="${esc(group.id)}" aria-label="Select ${esc(group.name)}" ${state.selectedContacts.has(group.id)?'checked':''}></td><td><b>${esc(group.name)}</b><small>WhatsApp group</small></td><td>${group.participants.length}</td><td>${employeeNames(group,workspace).map(name=>`<div>${esc(name)}</div>`).join('')||'Not assigned'}</td><td>${esc(branchLabels(group.branchIds))}</td><td>${esc(group.last?.body||'No captured messages')}<small>${esc(date(group.last?.created_at))}</small></td></tr>`).join('')}</tbody></table></div>`:empty('No synchronized groups match these filters.');}
function directoryFilterControls(f=directoryFilters[filterKey()]){
  const key=filterKey();
  const input=(field,label,type='search')=>`<label class="directory-filter">${label}<input id="directory-${key}-${field}" data-directory-filter="${field}" ${type==='date'?'type="text" data-app-date inputmode="none" autocomplete="off"':'type="'+type+'"'} ${type==='tel'?'inputmode="tel"':''} value="${esc(f[field])}" placeholder="${type==='date'?'YYYY-MM-DD':label}" aria-label="${label}"></label>`;
  const select=(field,label,options)=>`<label class="directory-filter">${label}<select id="directory-${key}-${field}" data-directory-filter="${field}" aria-label="${label}">${options.map(([value,text])=>`<option value="${esc(value)}" ${f[field]===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
  const employeeOptions=[...new Set([...workspace.employees.map(e=>e.name),...workspace.numbers.map(n=>n.responsible||n.name),...workspace.entities.map(e=>e.responsible)].filter(Boolean))].sort((a,b)=>a.localeCompare(b));
  const branch=()=>select('branch','Branch',[['all','All branches'],...workspace.branches.map(b=>[b.id,b.name])]);
  const employee=()=>select('employee','Employee',[['all','All employees'],...employeeOptions.map(name=>[name,name])]);
  const number=()=>select('number','Connected number',[['all','All connected numbers'],...workspace.numbers.map(n=>[n.id,`${n.name} (${n.phone||'Not paired'})`])]);
  let fields='';
  if(key==='logs')fields=select('account','WhatsApp account',[['all','All accounts'],...workspace.numbers.map(number=>[number.id,`${number.name} (${number.phone||'Not paired'})`])])+select('status','Event',[['all','All events'],...['Connected','Disconnected','Session expired','Reconnect requested','Contact deleted','Contact hidden','Contact restored','Group conversation deleted','Group hidden','Group restored'].map(status=>[status,status])])+input('dateFrom','Date from','date')+input('dateTo','Date to','date');
  else if(key==='numbers')fields=input('name','Account name')+input('phone','Phone number','tel')+branch()+employee()+select('status','Connection status',[['all','All statuses'],...['Connected','Connecting','Awaiting scan','Disconnected','Session expired'].map(status=>[status,status])]);
  else if(key==='employees')fields=input('name','Employee name')+branch();
  else if(['integrations','plivo','email'].includes(key))fields=input('name','Integration name')+(key==='plivo'?'':select('provider','Provider',[['all','All providers'],['zoho','Zoho Mail'],['gmail','Gmail'],['microsoft','Microsoft'],['imap','Other IMAP'],['plivo','Plivo']]))+select('status','Status',[['all','All statuses'],['Configured','Configured'],['Connected','Connected']]);
  else if(key==='branches')fields=input('name','Branch name')+input('city','Location')+employee()+number();
  else {
    fields=input('name',key==='groups'?'Group name':'Name');
    if(key!=='groups')fields+=input('phone','Phone number','tel');
    if(key!=='contacts')fields+=number();
    if(['groups','dashboard','conversations'].includes(key))fields+=select('group','Group',[['all',key==='groups'?'All groups':'All chats'],...(['dashboard','conversations'].includes(key)?[['direct','Direct contacts'],['groups','All groups']]:[]),...workspace.groups.map(e=>[e.id,e.name])]);
    fields+=branch()+employee()+select('messageType','Message type',[['all','All message types'],['text','Text messages'],['call','WhatsApp calls'],['audio','Audio / voice notes'],['image','Images'],['video','Videos'],['document','Documents'],['sticker','Stickers'],['location','Locations'],['contact','Contact cards'],['unknown','Other / unknown']])+input('dateFrom','Message date from','date')+input('dateTo','Message date to','date');
  }
  return `<div class="directory-filters">${fields}</div>`;
}
function contactsDirectoryPage(){
  const entries=filterDirectory(state.directoryTab==='groups'?{...workspace,entities:workspace.groups}:workspace,state.directoryTab,directoryFilters[state.directoryTab],state.query);
  const counts={all:workspace.entities.length,contacts:workspace.entities.filter(e=>e.kind==='contact').length,groups:workspace.groups.length};
  return `<div class="directory-toolbar"><div class="directory-tabs" role="tablist" aria-label="Contacts and groups">${[['all','All'],['contacts','Contacts'],['groups','Groups']].map(([id,label])=>`<button id="directory-tab-${id}" class="directory-tab ${state.directoryTab===id?'active':''}" role="tab" aria-selected="${state.directoryTab===id}" aria-controls="directory-panel" tabindex="${state.directoryTab===id?0:-1}" data-directory-tab="${id}">${label} <span>${counts[id]}</span></button>`).join('')}</div></div><div id="directory-panel" role="tabpanel" aria-labelledby="directory-tab-${state.directoryTab}"><section class="surface panel"><div class="panel-subtitle">${entries.length} ${entries.length===1?'result':'results'}</div>${bulkContactToolbar()}${state.directoryTab==='groups'?groupTable(entries):contactTable(entries)}</section></div>`;
}
