 modal('Vote in poll',`<h3>${esc(poll.title)}</h3><p>Voting as ${esc(account(accountId)?.name||'WhatsApp account')}</p><div class="poll-vote-options">${poll.options.map((option,index)=>`<label><input type="${single?'radio':'checkbox'}" name="poll-choice" value="${index}" ${option.selected?'checked':''}> ${esc(option.name)}</label>`).join('')}</div><p id="poll-vote-result" role="status"></p>`,`<button class="btn" data-close-modal>Close</button><button class="btn" data-action="clear-poll-vote">Clear selection</button><button class="btn btn-primary" data-action="save-poll-vote" data-id="${esc(token)}">Save vote</button>`);
