function integrationsPage(){return numbersPage();}
function organizationPage(){const create=state.organizationTab==='employees'?'<button class="btn btn-primary" data-action="add-employee">New employee</button>':'<button class="btn btn-primary" data-action="new-branch">Add branch</button>';return `<div class="user-tabs-row">${sectionTabs([['branches','Branches'],['employees','Employees']],state.organizationTab,'organization-tab','Branches and employees')}${create}</div>`+(state.organizationTab==='employees'?employeesPage():branchesPage());}
