function voiceSettingsModal(){modal('Voice callback configuration',`<p>Plivo needs a public HTTPS URL pointing to the callback-only listener. The main application remains local.</p><div class="field"><label>Public callback URL</label><input id="voice-public-url" value="${esc(workspace.voiceSettings.publicUrl||'')}" placeholder="https://your-callback-host.example"></div><p>Callback listener: 127.0.0.1:${esc(workspace.voiceSettings.callbackPort||3002)}</p><p id="voice-settings-result" role="status"></p>`,`<button class="btn" data-close-modal>Close</button><button class="btn btn-primary" data-action="save-voice-settings">Save</button>`);}
function openDialer(to='',employeeId=''){const staff=workspace.employees.filter(e=>e.plivoNumbers.some(id=>workspace.plivoNumbers.find(n=>n.id===id&&n.voice)));modal('Voice call',`<div class="field"><label>Employee</label><select id="dial-employee">${staff.map(e=>`<option value="${esc(e.id)}" ${e.id===employeeId?'selected':''}>${esc(e.name)}</option>`).join('')||'<option value="">Assign a Plivo number to an employee first</option>'}</select></div><div class="field"><label>Call from</label><select id="dial-number"></select></div><div class="field"><label>Destination number</label><input id="dial-to" type="tel" placeholder="+91?" value="${esc(to)}"></div><p>Voice calls are recorded and stored in the database.</p><p id="dial-result" role="status">${workspace.voiceSettings.publicUrl?'':'Configure a public callback URL in Integrations before calling.'}</p>`,`<button class="btn" data-close-modal>Close</button><button class="btn btn-primary" data-action="start-voice-call">Start voice call</button>`);updateDialerNumbers();}
