  if(action==='restore-hidden-contact'){const button=document.querySelector('[data-action="restore-hidden-contact"][data-id="'+CSS.escape(id)+'"]');if(button)button.disabled=true;try{await api('/crm/hidden/'+encodeURIComponent(id),'DELETE');await refreshLive();hiddenContactsModal();toast('Contact enabled. Future messages will appear again.');}catch(error){const result=document.getElementById('hidden-contact-result');if(result)result.textContent=error.message;if(button)button.disabled=false;}return;}
  if(action==='restore-hidden-group'){const button=document.querySelector('[data-action="restore-hidden-group"][data-id="'+CSS.escape(id)+'"]');if(button)button.disabled=true;try{await api('/crm/hidden-group/'+encodeURIComponent(id),'DELETE');await refreshLive();hiddenGroupsModal();toast('Group enabled. Future messages will appear again.');}catch(error){const result=document.getElementById('hidden-group-result');if(result)result.textContent=error.message;if(button)button.disabled=false;}return;}
  if(action==='confirm-delete-contacts'){if(state.bulkDeleting||!pendingContactDeleteIds.length)return;const contacts=buildUnifiedContacts(workspace),ids=[...pendingContactDeleteIds],hideFuture=!!document.getElementById('hide-future-contact')?.checked,button=document.querySelector('[data-action="confirm-delete-contacts"]');state.bulkDeleting=true;button.disabled=true;let deleted=0;try{for(const id of ids){await api('/crm/conversation','DELETE',{id,hideFuture});const contact=contacts.find(c=>c.id===id);state.selectedContacts.delete(id);for(const key of [...state.selectedContacts])if(contact?.entities.some(e=>contactSelectionId(e)===key))state.selectedContacts.delete(key);deleted++;}pendingContactDeleteIds=[];state.selected=null;state.composerOpen=false;closeModal();await refreshLive();toast(deleted+' conversation'+(deleted===1?'':'s')+' deleted'+(hideFuture?' and added to the hidden list.':'.'));}catch(error){document.getElementById('delete-contact-result').textContent=error.message;button.disabled=false;}finally{state.bulkDeleting=false;}return;}
