  if(action==='toggle-emoji-picker'){const picker=document.getElementById('emoji-picker'),button=document.querySelector('[data-action="toggle-emoji-picker"]');if(!picker)return;picker.hidden=!picker.hidden;button?.setAttribute('aria-expanded',String(!picker.hidden));return;}
