function setNavigation(){document.body.classList.remove('navigation-open');}
let pollingQR=false;
setInterval(async()=>{if(pollingQR||!pairingId||!document.getElementById('live-qr'))return;pollingQR=true;const id=pairingId;try{const s=await api(`/accounts/${encodeURIComponent(id)}`);const target=document.getElementById('live-qr');if(!target||pairingId!==id)return;if(s.status==='Connected'){target.innerHTML=connectedVisual();pairingId=null;pairingQr='';pairingQrExpiresAt=0;toast('WhatsApp connected. Synchronizing live records.');await refreshLive();return;}if(s.qr){if(s.qr!==pairingQr){pairingQr=s.qr;pairingQrExpiresAt=Date.now()+20000;target.replaceChildren();const img=document.createElement('img');img.src=s.qr;img.alt='Live WhatsApp pairing QR';img.width=240;const countdown=document.createElement('p');countdown.className='qr-countdown';target.append(img,countdown);}const countdown=target.querySelector('.qr-countdown');if(countdown){const seconds=Math.max(0,Math.ceil((pairingQrExpiresAt-Date.now())/1000));countdown.textContent=`QR refreshes in ${seconds} second${seconds===1?'':'s'}`;}}else{pairingQr='';pairingQrExpiresAt=0;target.innerHTML=pairingLoading();if(s.error){const error=document.createElement('p');error.className='qr-error';error.textContent=s.error;target.append(error);}}}catch(error){const target=document.getElementById('live-qr');if(target){target.innerHTML=pairingLoading();const message=document.createElement('p');message.className='qr-error';message.textContent=error.message;target.append(message);}}finally{pollingQR=false;}},1000);
window.addEventListener('hashchange',()=>{restoreSectionRoute();closeModal();render();});
setInterval(refreshLive,5000);render();setAppLoading(true,'Loading workspace...');refreshLive().finally(()=>setAppLoading(false));
